import { Product } from '../../domain/product/Product';

export interface StockLevelDto {
  productId: string;
  name: string;
  stockLevel: number;
}

export function toStockLevelDto(product: Product): StockLevelDto {
  return { productId: product.id, name: product.name, stockLevel: product.stockLevel };
}

